const [stats, orders] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: 'http://5.189.170.55:4000/api/stats' }),
  this.helpers.httpRequest({ method: 'GET', url: 'http://5.189.170.55:4000/api/orders' })
]);
const today = new Date();
const todayOrders = (orders||[]).filter(o => new Date(o.created_at).toDateString() === today.toDateString());
const revenueToday = todayOrders.filter(o=>o.status==='delivered').reduce((s,o)=>s+(parseInt((o.price||'0').replace(/[^0-9]/g,''))||0),0);
const revenueMonth = (orders||[]).filter(o=>o.status==='delivered'&&new Date(o.created_at).getMonth()===today.getMonth()).reduce((s,o)=>s+(parseInt((o.price||'0').replace(/[^0-9]/g,''))||0),0);
return [{ json: { revenue_today: revenueToday, revenue_month: revenueMonth, orders_today: todayOrders.length, orders_new: todayOrders.filter(o=>o.status==='new').length, orders_delivered: todayOrders.filter(o=>o.status==='delivered').length, total_customers: stats?.customers||0, messages_today: stats?.messages_today||0, available_products: stats?.available||0 } }];
